    /// <summary>
    /// Toggles whether the current user has sponsored messages enabled. The setting has no effect for users without Telegram Premium for which sponsored messages are always enabled
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ToggleHasSponsoredMessagesEnabledAsync(bool hasSponsoredMessagesEnabled = default)
    {

           using var activity =  StartCallActivity("ToggleHasSponsoredMessagesEnabledAsync", typeof(ToggleHasSponsoredMessagesEnabled).FullName ?? "ToggleHasSponsoredMessagesEnabledAsync");

           try
           {
             return client.ToggleHasSponsoredMessagesEnabledAsync(hasSponsoredMessagesEnabled);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
